const health = $('Fetch Health & Attention').first()?.json || {};
const pipeline = $('Fetch Engagement Pipeline').first()?.json || {};
const outstanding = $('Fetch Outstanding Work').first()?.json || {};

// Format Africa/Lagos reference time
const now = new Date();
const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
const lagosTime = new Date(utc + (3600000)); // UTC+1
const dateStr = lagosTime.toLocaleDateString('en-GB', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});
const timeStr = lagosTime.toLocaleTimeString('en-GB', {
  hour: '2-digit',
  minute: '2-digit'
});

const totalPipelineValue = pipeline.total_pipeline_value || pipeline.pipeline_value || 0;
const activeCount = pipeline.active_count || (pipeline.pipeline || []).length || 0;
const qualifiedCount = pipeline.qualified_count || 0;

const dueFollowUps = outstanding.due_follow_ups || [];
const overdueTasks = outstanding.overdue_tasks || [];
const attentionItems = health.attention || {};

let msg = '📊 DAILY BUSINESS BRIEFING\n━━━━━━━━━━━━━━━━━━━━\n\n';
msg += '📅 DATE\n' + dateStr + ', ' + timeStr + ' (Africa/Lagos)\n\n';

msg += '💰 PIPELINE\n';
msg += '• Total pipeline: ₦' + Number(totalPipelineValue).toLocaleString() + '\n';
msg += '• Active prospects: ' + activeCount + '\n';
msg += '• Qualified prospects: ' + qualifiedCount + '\n\n';

msg += '🚨 OVERDUE & ATTENTION\n';
if (dueFollowUps.length === 0 && overdueTasks.length === 0) {
  msg += '• No overdue tasks or past-due follow-ups recorded.\n';
} else {
  if (dueFollowUps.length > 0) {
    msg += '• Past-due follow-ups: ' + dueFollowUps.length + ' requiring review\n';
  }
  if (overdueTasks.length > 0) {
    msg += '• Overdue tasks: ' + overdueTasks.length + ' pending\n';
  }
}
msg += '\n';

msg += '🎯 RECOMMENDED ACTIONS\n';
msg += '1. Recommendation: Review active pipeline prospects and confirm next follow-up dates.\n';
msg += '   Reason: Regular review maintains consistent outreach pace.\n\n';
msg += '2. Recommendation: Inspect any flagged attention items in operator console.\n';
msg += '   Reason: Resolving pending items prevents operational bottlenecks.\n';

// Chunk message to mobile limit <= 3900 chars
const MAX_LENGTH = 3900;
const chunks = [];
let remaining = msg.trim();

while (remaining.length > MAX_LENGTH) {
  let splitAt = remaining.lastIndexOf('\n\n', MAX_LENGTH);
  if (splitAt < 2000) splitAt = remaining.lastIndexOf('\n', MAX_LENGTH);
  if (splitAt < 1) splitAt = MAX_LENGTH;
  chunks.push(remaining.slice(0, splitAt).trim());
  remaining = remaining.slice(splitAt).trim();
}
if (remaining) chunks.push(remaining);

return chunks.map((chunk, idx) => ({
  json: {
    telegram_text: chunks.length > 1 ? 'Nior — Daily Briefing (Part ' + (idx + 1) + '/' + chunks.length + ')\n\n' + chunk : chunk,
    part_number: idx + 1,
    total_parts: chunks.length
  }
}));
